  1961	
  1962	        while(off < line_end) {
  1963	            if(CH(off) == _T('\\')  &&  off+1 < ctx->size  &&  (ISPUNCT(off+1) || ISNEWLINE(off+1))) {
  1964	                if(contents_end == 0) {
